   234→// TokenUsage represents aggregated token usage for a checkpoint
   235→type TokenUsage struct {
   236→	// InputTokens is the number of input tokens (fresh, not from cache)
   237→	InputTokens int `json:"input_tokens"`
   238→	// OutputTokens is the number of output tokens generated
   239→	OutputTokens int `json:"output_tokens"`
   240→	// CacheReadTokens is the number of tokens read from cache
   241→	CacheReadTokens int `json:"cache_read_tokens"`
   242→	// APICallCount is the number of API calls made
   243→	APICallCount int `json:"api_call_count"`
   244→}
   245→
   246→// CalculateTokenUsage calculates token usage from a Gemini transcript.
   247→// This is specific to Gemini's API format where each message may have a tokens object
   248→// with input, output, cached, thoughts, tool, and total counts.
   249→// Only processes messages from startMessageIndex onwards (0-indexed).
   250→func CalculateTokenUsage(data []byte, startMessageIndex int) *TokenUsage {
   251→	var transcript struct {
   252→		Messages []geminiMessageWithTokens `json:"messages"`
   253→	}
   254→
   255→	if err := json.Unmarshal(data, &transcript); err != nil {
   256→		return &TokenUsage{}
   257→	}
   258→
   259→	usage := &TokenUsage{}
   260→
   261→	for i, msg := range transcript.Messages {
   262→		// Skip messages before startMessageIndex
   263→		if i < startMessageIndex {
   264→			continue
   265→		}
   266→
   267→		// Only count tokens from gemini (assistant) messages
   268→		if msg.Type != MessageTypeGemini {
   269→			continue
   270→		}
   271→
   272→		if msg.Tokens == nil {
   273→			continue
   274→		}
   275→
   276→		usage.APICallCount++
   277→		usage.InputTokens += msg.Tokens.Input
   278→		usage.OutputTokens += msg.Tokens.Output
   279→		usage.CacheReadTokens += msg.Tokens.Cached
   280→	}
   281→
   282→	return usage
   283→}
